<script>
const plans={hotel:{small:{title:'Small Hotel / Guest House',subtitle:'For boutique stays, motels, and guest houses.',prices:{monthly:29,annual:290,lifetime:899},limits:['Up to 15 rooms','1 front desk terminal','Single-user access','Basic housekeeping','No multi-branch'],features:['Room check-in and check-out','Guest profiling and history','Basic invoicing','Housekeeping tracker']},medium:{title:'Medium & Large Hotel',subtitle:'Multi-department control for growing hotels.',prices:{monthly:79,annual:790,lifetime:2299},limits:['Up to 60 rooms','Up to 5 terminals','Single-location setup'],features:['Restaurant and bar POS','Inventory control','Staff payroll','WhatsApp alerts','Advanced analytics']},enterprise:{title:'5-Star Luxury Resort & Chain',subtitle:'Enterprise control for luxury hotels and hotel groups.',prices:{monthly:199,annual:1990,lifetime:5499},limits:['Unlimited rooms','Unlimited terminals'],features:['Multi-branch management','OTA channel manager','ERP integration','Custom API','Dedicated account manager','24/7 support']}},clinic:{small:{title:'Small Practice / Single Doctor',subtitle:'Essential tools for individual clinics.',prices:{monthly:19,annual:190,lifetime:599},limits:['1 doctor seat','Up to 50 patients per day','OPD only'],features:['E-prescriptions','Patient EHR','Basic OPD billing']},medium:{title:'Polyclinic / Multi-Specialty',subtitle:'Comprehensive software for multiple doctors.',prices:{monthly:59,annual:590,lifetime:1699},limits:['Up to 5 doctor seats','Unlimited patients'],features:['OPD and IPD billing','Pharmacy and stock','Lab reports','SMS reminders']},enterprise:{title:'Medical Center / Hospital',subtitle:'Complete healthcare management for large centers.',prices:{monthly:149,annual:1490,lifetime:3999},limits:['Unlimited doctors and staff','Multi-ward management'],features:['Pharmacy ERP','Diagnostic integrations','Insurance claims','Custom EMR','24/7 support']}}};let industry=new URLSearchParams(location.search).get('system')==='clinic'?'clinic':'hotel';let currency=new URLSearchParams(location.search).get('currency')==='USD'?'USD':'PKR';let tier='small';let cycle='annual';const rate=280;function render(){const plan=plans[industry][tier];document.querySelectorAll('[data-industry]').forEach(b=>b.classList.toggle('active',b.dataset.industry===industry));document.querySelectorAll('[data-currency]').forEach(b=>b.classList.toggle('active',b.dataset.currency===currency));document.querySelectorAll('[data-cycle]').forEach(b=>b.classList.toggle('active',b.dataset.cycle===cycle));document.getElementById('tiers').innerHTML=[['small','▣',industry==='hotel'?'Small Hotel':'Small Practice',industry==='hotel'?'Up to 15 rooms':'Single doctor'],['medium','⌂',industry==='hotel'?'Medium / Large Hotel':'Polyclinic',industry==='hotel'?'Up to 60 rooms':'Up to 5 doctors'],['enterprise','♛',industry==='hotel'?'5-Star Luxury Hotel':'Medical Center',industry==='hotel'?'Unlimited rooms':'Unlimited staff']].map(x=>`<button class="tier ${x[0]===tier?'active':''}" data-tier="${x[0]}"><div class="tier-icon">${x[1]}</div><h3>${x[2]}</h3><p>${x[3]}</p></button>`).join('');const base=plan.prices[cycle];const total=currency==='PKR'?base*rate:base;document.getElementById('planTitle').textContent=plan.title;document.getElementById('planSubtitle').textContent=plan.subtitle;document.getElementById('price').textContent=(currency==='PKR'?'Rs. ':'$')+total.toLocaleString();document.getElementById('cycleLabel').textContent=cycle==='monthly'?'/ month':cycle==='annual'?'/ year':'one-time payment';document.getElementById('limits').innerHTML=plan.limits.map(x=>`<li><span class="limit">•</span>${x}</li>`).join('');document.getElementById('features').innerHTML=plan.features.map(x=>`<li><span class="feature">✓</span>${x}</li>`).join('');document.getElementById('startLink').href='/register/'+industry+'?plan='+tier+'&cycle='+cycle+'&currency='+currency;document.querySelectorAll('[data-tier]').forEach(b=>b.onclick=()=>{tier=b.dataset.tier;render()})}document.querySelectorAll('[data-industry]').forEach(b=>b.onclick=()=>{industry=b.dataset.industry;tier='small';render()});document.querySelectorAll('[data-currency]').forEach(b=>b.onclick=()=>{currency=b.dataset.currency;render()});document.querySelectorAll('[data-cycle]').forEach(b=>b.onclick=()=>{cycle=b.dataset.cycle;render()});render();
</script></body></html>
